<script setup lang="ts">
const route = useRoute(); const { data: publication, error } = await useFetch<any>(`/api/publications/${route.params.slug}`)
if (error.value) throw createError({ statusCode: 404, statusMessage: 'Publicación no encontrada' })
useSeoMeta({ title: () => publication.value?.title || 'NUVIB', description: () => publication.value?.content?.slice(0, 150) || '' })
const formatCurrency = (value: number) => new Intl.NumberFormat('es-CO', { style: 'currency', currency: 'COP', maximumFractionDigits: 0 }).format(Number(value || 0))
</script>

<template><article v-if="publication" class="container publication-detail"><NuxtLink to="/blog" class="back-link">← Volver a publicaciones</NuxtLink><p class="eyebrow">{{ new Date(publication.publishedAt).toLocaleDateString('es-CO') }}</p><h1>{{ publication.title }}</h1><div v-if="publication.images?.length || publication.image" class="publication-gallery"><img v-for="(image, index) in (publication.images?.length ? publication.images : [publication.image])" :key="image" :src="image" :alt="`${publication.title} - imagen ${index + 1}`"></div><div class="publication-content" v-html="publication.content"></div><aside v-if="publication.product" class="publication-product"><div><p class="eyebrow">Producto relacionado</p><h2>{{ publication.product.name }}</h2><strong>{{ formatCurrency(publication.product.price) }}</strong><p v-if="publication.product.stock !== undefined">{{ publication.product.stock }} disponibles</p><div v-if="publication.product.options?.sizes?.length || publication.product.options?.colors?.length" class="publication-product-options"><span v-if="publication.product.options.sizes?.length">Tallas: {{ publication.product.options.sizes.join(', ') }}</span><span v-if="publication.product.options.colors?.length">Colores: {{ publication.product.options.colors.join(', ') }}</span></div></div><NuxtLink class="button" :to="`/productos/${publication.product.slug}`">Ver producto</NuxtLink></aside></article></template>
